		w.WriteHeader(http.StatusOK)
	}))
	defer ts.Close()

	novuClient, err := novu.NewAPIClient(ts.URL, &novu.Config{ApiKey: "test-api-key"})
	assert.NoError(t, err)

	event := &event.Event{
		Type: "test",
	}

